#' Automatic Report for Independent Samples T-Test
#'
#' 
#' @section References:
#' RCore
#'
#' jReport
#'
#' jmvcore
#'
#' effectsize
#'
#' BayesFactor
#'
#' @param data .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$jReportHeading} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$jReportApaTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$jReportAssumptions} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$jReportCard} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$jReportApaTable$asDF}
#'
#' \code{as.data.frame(results$jReportApaTable)}
#'
#' @export
jrReportTTestIS <- function(
    data) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("jrReportTTestIS requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- jrReportTTestISOptions$new()

    analysis <- jrReportTTestISClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

